"""Static game data (generated by scripts/import_data.py from data_manual/ + the upstream repo)."""
import json
import re
from functools import lru_cache
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent
_BGA_ID = re.compile(r"^([ASPF])(\d+)_([A-Za-z0-9_]+?)(_MW)?$")


@lru_cache(maxsize=None)
def _load(name: str) -> list:
    return json.loads((DATA_DIR / f"{name}.json").read_text("utf8"))


def animals() -> list[dict]:
    return _load("animals")


def sponsors() -> list[dict]:
    return _load("sponsors")


def projects() -> list[dict]:
    return _load("projects")


def endgames() -> list[dict]:
    return _load("endgames")


def maps() -> list[dict]:
    return _load("maps")


@lru_cache(maxsize=None)
def cards_by_key() -> dict[str, dict]:
    """All cards keyed by letter+number (A414, S231, P127, F003)."""
    return {c["key"]: c for f in (animals, sponsors, projects, endgames) for c in f()}


def parse_bga_card_id(bga_id: str) -> tuple[str, bool]:
    """'F001_LargeAnimalZoo_MW' -> ('F001', True): (card key, is Marine Worlds variant)."""
    m = _BGA_ID.match(bga_id)
    if not m:
        raise ValueError(f"not a BGA card id: {bga_id!r}")
    return f"{m.group(1)}{int(m.group(2)):03d}", bool(m.group(4))


@lru_cache(maxsize=None)
def _legacy_map(map_id: str) -> dict:
    from ark_nova.data import map_quirks
    return map_quirks.legacy_map(map_by_id(map_quirks.base_map_id(map_id)), map_id)


CUSTOM_PREFIX = "custom-"                 # the id of a map made in the map editor (engine/custom_map.py): `custom-<hash of its content>`
_CUSTOM: dict = {}                         # id -> record, filled by `register_map` whenever a state that carries a custom map is built or loaded


def is_custom_map(map_id: str) -> bool:
    return str(map_id).startswith(CUSTOM_PREFIX)


BDW_PREFIX = "BDW"                        # the Board Design Workshop maps BDW1..BDW4 (data/bdw_maps.json, docs/bdw_maps.md): not part of `maps()`, only in the pool of a game that asks for them


def is_bdw_map(map_id: str) -> bool:
    return str(map_id).startswith(BDW_PREFIX)


def bdw_maps() -> list[dict]:
    return _load("bdw_maps")


def has_association_record(map_id: str) -> bool:
    """Maps whose association board is described by their record (`association`) instead of data/association_bonuses.json: the maps of the map editor and the BDW maps."""
    return is_custom_map(map_id) or is_bdw_map(map_id)


def register_map(rec: dict) -> None:
    _CUSTOM[rec["id"]] = rec


def map_by_id(map_id: str) -> dict:
    """`map_id` may be a legacy id ('6a-legacy', see data/map_quirks.py): the map as BGA played it in older tables."""
    if str(map_id).endswith("-legacy"):
        return _legacy_map(str(map_id))
    if str(map_id) in _CUSTOM:
        return _CUSTOM[str(map_id)]
    for m in maps():
        if m["id"] == str(map_id):
            return m
    for m in bdw_maps():
        if m["id"] == str(map_id):
            return m
    raise KeyError(map_id)
